  else {
    if (!['PLANNING', 'PRE_REVIEW', 'IMPLEMENTATION', 'CLOSURE'].includes(scope.mode))
      add(issues, 'SCOPE_MODE', 'scope.mode', 'Unknown mode')
    for (const key of ['allowed', 'planningAllowed', 'frozen']) {
      if (!Array.isArray(scope[key]) || !scope[key].length)
        add(issues, 'SCOPE_LIST', `scope.${key}`, 'Nonempty list required')
      else
        scope[key].forEach((p, i) => {
          if (!safeRepoPath(p, { glob: true }))
            add(issues, 'UNSAFE_PATH', `scope.${key}[${i}]`, 'Unsafe path')
        })
    }
    for (const a of Array.isArray(scope.allowed) ? scope.allowed : [])
      for (const f of Array.isArray(scope.frozen) ? scope.frozen : [])
        if (safeRepoPath(a, { glob: true }) && safeRepoPath(f, { glob: true }) && overlap(a, f))
          add(issues, 'FROZEN_OVERLAP', 'scope.allowed', `${a} intersects ${f}`)
    if (
      safeRepoPath(m.statusPath) &&
      (!Array.isArray(scope.allowed) ||
        !scope.allowed.some((p) => pathMatches(p, m.statusPath)) ||
        !Array.isArray(scope.planningAllowed) ||
        !scope.planningAllowed.some((p) => pathMatches(p, m.statusPath)) ||
        !Array.isArray(scope.frozen) ||
        scope.frozen.some((p) => pathMatches(p, m.statusPath)))
    )
      add(
        issues,
        'STATUS_SCOPE',
        'statusPath',
        'Status path must stay in owning planning and implementation scope',
      )
    const c = scope.closure
    if (
      !obj(c) ||
      typeof c.enabled !== 'boolean' ||
      !safeId(c.archiveOwner) ||
      !Array.isArray(c.requires) ||
      BARRIERS.some((x) => !c.requires.includes(x))
    )
      add(issues, 'CLOSURE_CONTRACT', 'scope.closure', 'Owner and barriers required')
    const specs = c?.specDestinations
    if (
      !Array.isArray(specs) ||
      !specs.length ||
      specs.some(
        (p) =>
          typeof p !== 'string' ||
          !/^openspec\/specs\/[a-z][a-z0-9]*(?:-[a-z0-9]+)*\/spec\.md$/.test(p) ||
          !safeRepoPath(p),
      ) ||
      new Set(specs.map((p) => p?.toLowerCase())).size !== specs.length ||
      (m.id === 'frade-standard-workflow' &&
        (specs.length !== W01_SPECS.length || specs.some((p) => !W01_SPECS.includes(p))))
    )
      add(
        issues,
        'CLOSURE_DESTINATION',
        'scope.closure.specDestinations',
        'Exact safe capability spec paths required',
      )
    if (
      c?.archiveDestination !==
      `openspec/changes/archive/<actual-archive-date>-${c?.archiveOwner}/**`
    )
      add(
        issues,
        'ARCHIVE_DESTINATION',
        'scope.closure.archiveDestination',
        'Archive must bind exact owner',
      )
  }
  if (!Array.isArray(m.stages) || !m.stages.length)
    add(issues, 'STAGES', 'stages', 'Stage list required')
  else {
    const seen = new Set()
    const changes = new Set()
    for (const [i, s] of m.stages.entries()) {
      const p = `stages[${i}]`
      if (!obj(s) || typeof s.id !== 'string' || !/^[A-Z][A-Z0-9]*$/.test(s.id) || seen.has(s.id))
        add(issues, 'STAGE_ID', `${p}.id`, 'Unique stage ID required')
      seen.add(s?.id)
      if (
        !safeId(s?.change) ||
        changes.has(s.change) ||
        !Array.isArray(m.scope?.planningAllowed) ||
        !m.scope.planningAllowed.some((path) =>
          pathMatches(path, `openspec/changes/${s.change}/proposal.md`),
        )
      )
        add(
          issues,
          'STAGE_OWNER',
          `${p}.change`,
          'Stage change must be safe, unique and in owned planning scope',
        )
      changes.add(s?.change)
      if (!PHASES.includes(s?.phase)) add(issues, 'PHASE', `${p}.phase`, 'Unknown phase')
      if (!HEALTH.includes(s?.health)) add(issues, 'HEALTH', `${p}.health`, 'Unknown health')
      if (
        !Array.isArray(s?.dependencies) ||
        s.dependencies.some((x) => typeof x !== 'string' || !/^[A-Z][A-Z0-9]*$/.test(x))
      )
        add(issues, 'DEPENDENCIES', `${p}.dependencies`, 'Dependencies required')
      if (
        s?.tasks !== undefined &&
        (!Array.isArray(s.tasks) ||
          s.tasks.some((t) => !obj(t) || typeof t.id !== 'string' || !t.id))
      )
        add(issues, 'TASK_SHAPE', `${p}.tasks`, 'Task records must have stable IDs')
      if (
        s?.failedFixes !== undefined &&
        (!Array.isArray(s.failedFixes) ||
          s.failedFixes.some(
            (f) =>
              !obj(f) ||
              typeof f.defectId !== 'string' ||
              !f.defectId ||
              typeof f.deterministic !== 'boolean' ||
              f.status !== 'FAIL',
          ))
      )
        add(
          issues,
          'FAILED_FIXES',
          `${p}.failedFixes`,
          'Recorded failed fixes require stable defect and deterministic classification',
        )
      if (s?.rca !== undefined && !obj(s.rca))
        add(issues, 'RCA_SHAPE', `${p}.rca`, 'RCA object required')
      if (s?.admission !== undefined && !obj(s.admission))
        add(issues, 'GATE_CLAIM', `${p}.admission`, 'Admission object required')
      for (const [key, claim] of Object.entries(obj(s?.admission) ? s.admission : {}))
        if (typeof claim !== 'string' || /^(?:true|false)$/i.test(claim))
          add(issues, 'GATE_CLAIM', `${p}.admission.${key}`, 'Boolean gate claim forbidden')
    }
    const stageIds = new Set(m.stages.map((s) => s?.id))
    for (const [i, s] of m.stages.entries())
      if (Array.isArray(s?.dependencies))
        for (const dep of s.dependencies)
          if (!stageIds.has(dep) || dep === s.id)
            add(
              issues,
              'DEPENDENCIES',
              `stages[${i}].dependencies`,
              'Unknown or self stage dependency',
            )
    const stageById = new Map(m.stages.filter(obj).map((s) => [s.id, s]))
    const visited = new Set(),
      visiting = new Set()
    const cycle = (id) => {
      if (visiting.has(id)) return true
      if (visited.has(id)) return false
      visiting.add(id)
      const found = (
        Array.isArray(stageById.get(id)?.dependencies) ? stageById.get(id).dependencies : []
      ).some((dep) => stageById.has(dep) && cycle(dep))
      visiting.delete(id)
      visited.add(id)
      return found
    }
    if ([...stageById.keys()].some(cycle))
      add(issues, 'DEPENDENCIES', 'stages', 'Circular stage dependency')
    if (!changes.has(m.scope?.closure?.archiveOwner))
      add(
        issues,
        'STAGE_OWNER',
        'scope.closure.archiveOwner',
        'Closure owner must be an owned stage change',
      )
  }
  return outcome(issues)
}

export function validateTraceability(t, { action = 'IMPLEMENTATION' } = {}) {
  const issues = []
  if (
    !obj(t) ||
    !['requirements', 'scenarios', 'tasks', 'assertions', 'runs'].every((k) => Array.isArray(t[k]))
  )
    return outcome([{ code: 'TRACE_SHAPE', path: '$', detail: 'Trace arrays required' }])
  const maps = Object.fromEntries(
    ['requirements', 'scenarios', 'tasks', 'assertions', 'runs'].map((k) => [
      k,
      new Map(t[k].map((x) => [x?.id, x])),
    ]),
  )
  for (const k of Object.keys(maps))
    if (maps[k].size !== t[k].length) add(issues, 'TRACE_DUPLICATE', k, 'Duplicate ID')
  for (const r of t.requirements) {
    if (
      typeof r?.id !== 'string' ||
      !/^[A-Z][A-Z0-9]*(?:-[A-Z0-9]+)+$/.test(r.id) ||
      r.id.length > 80
    )
      add(issues, 'REQUIREMENT_ID', 'requirements', 'Stable generic ID required')
    if (r?.unresolved?.length && !['INTAKE', 'RESEARCH'].includes(action))
      add(issues, 'UNRESOLVED_ACCEPTANCE', r?.id, 'Dependent work blocked')
    const linked = Array.isArray(r?.scenarioIds)
      ? r.scenarioIds.map((id) => maps.scenarios.get(id))
      : []
    if (!linked.length || linked.some((s) => !s || s.requirementId !== r?.id))
      add(issues, 'TRACE_SCENARIO', r?.id, 'Scenario link missing')
    if (r?.critical)
      for (const control of ['positive', 'negative', 'boundary'])
        if (!linked.some((s) => s?.control === control))
          add(issues, `CONTROL_${control.toUpperCase()}`, r?.id, `Missing ${control} control`)
  }
  for (const s of t.scenarios) {
    if (!maps.requirements.has(s?.requirementId))
      add(issues, 'TRACE_REQUIREMENT', s?.id, 'Unknown requirement')
    if (!['positive', 'negative', 'boundary', 'human', 'future'].includes(s?.control))
      add(issues, 'TRACE_CONTROL', s?.id, 'Control class required')
    if (
      ['human', 'future'].includes(s?.control) &&
      (typeof s.boundaryReason !== 'string' || s.boundaryReason.trim().length < 20)
    )
      add(issues, 'TRACE_BOUNDARY_REASON', s?.id, 'Explicit human/future boundary required')
    if (
      !Array.isArray(s?.taskIds) ||
      !s.taskIds.length ||
      s.taskIds.some(
        (id) =>
          !maps.tasks.has(id) ||
          !Array.isArray(maps.tasks.get(id)?.scenarioIds) ||
          !maps.tasks.get(id).scenarioIds.includes(s?.id),
      )
    )
      add(issues, 'TRACE_TASK', s?.id, 'Reciprocal task link missing')
    if (
      !['human', 'future'].includes(s?.control) &&
      (!Array.isArray(s?.assertionIds) ||
        !s.assertionIds.length ||
        s.assertionIds.some((id) => !maps.assertions.has(id)))
    )
      add(issues, 'TRACE_ASSERTION', s?.id, 'Executable assertion missing')
  }
  for (const a of t.assertions)
    if (!maps.runs.has(a?.runId)) add(issues, 'TRACE_RUN', a?.id, 'Actual run missing')
  for (const r of t.runs)
    if (
      !hash64(r?.sourceSha256) ||
      !hash64(r?.configSha256) ||
      typeof r?.environment !== 'string' ||
      !r.environment.trim() ||
      !['PASS', 'FAIL', 'BLOCKED'].includes(r?.status)
    )
      add(issues, 'RUN_BINDING', r?.id, 'Source/config/environment binding required')
  return outcome(issues)
}

export async function verifyTraceability(
  trace,
  { boundary, snapshot, action = 'IMPLEMENTATION' } = {},
) {
  const issues = [...validateTraceability(trace, { action }).issues]
  const { verifyGate } = await import('./evidence.mjs')
  if (!hash64(snapshot?.sourceSha256) || !hash64(snapshot?.configSha256))
    add(issues, 'TRACE_SNAPSHOT', 'snapshot', 'Current source/config hashes required')
  const referenced = new Set(
    (Array.isArray(trace?.assertions) ? trace.assertions : []).map((a) => a?.runId),
  )
  for (const run of (Array.isArray(trace?.runs) ? trace.runs : []).filter((r) =>
    referenced.has(r?.id),
  )) {
    if (
      run?.status !== 'PASS' ||
      run?.sourceSha256 !== snapshot?.sourceSha256 ||
      run?.configSha256 !== snapshot?.configSha256 ||
      !(await verifyGate(boundary, 'run', run, {
        sourceSha256: snapshot?.sourceSha256,
        configSha256: snapshot?.configSha256,
      }))
    )
      add(issues, 'TRACE_RUN_PROOF', run?.id, 'Current trusted raw run proof required')
  }
  return outcome(issues)
}

export function validateApplicability(plan = {}) {
  if (!obj(plan))
    return outcome([{ code: 'APPLICABILITY_SHAPE', path: '$', detail: 'Plan object required' }])
  const { checks, affectedContracts = [], previousResults = [] } = plan
  const issues = []
  if (
    !Array.isArray(checks) ||
    !Array.isArray(affectedContracts) ||
    !Array.isArray(previousResults)
  )
    return outcome([{ code: 'APPLICABILITY_SHAPE', path: '$', detail: 'Arrays required' }])
  for (const c of checks) {
    if (!APPLICABILITY.includes(c?.applicability))
      add(issues, 'APPLICABILITY', c?.id, 'Unknown applicability')
    if (c?.applicability === 'NOT_APPLICABLE') {
      if (
        affectedContracts.includes(c.contract) ||
        previousResults.some((r) => r?.id === c.id && r?.status === 'FAIL')
      )
        add(issues, 'FALSE_NOT_APPLICABLE', c.id, 'Affected or failing check cannot be waived')
      if (typeof c.reason !== 'string' || c.reason.trim().length < 20)
        add(issues, 'NA_REASON', c.id, 'Contract reason required')
    }
    if (c?.applicability === 'REQUIRED' && c.status !== 'PASS')
      add(issues, 'REQUIRED_CHECK_NOT_PASS', c.id, 'Required run not passing')
  }
  return outcome(issues)
}

export async function verifyApplicability(plan, options = {}) {
  const validation = validateApplicability(plan)
  if (!validation.ok) return validation
  if (!obj(options))
    return outcome([
      { code: 'APPLICABILITY_OPTIONS_SHAPE', path: '$', detail: 'Options object required' },
    ])
  const { boundary, snapshot } = options
  const issues = []
  const { verifyGate } = await import('./evidence.mjs')
  if (!hash64(snapshot?.sourceSha256) || !hash64(snapshot?.configSha256))
    add(issues, 'CHECK_SNAPSHOT', 'snapshot', 'Current source/config hashes required')
  for (const c of Array.isArray(plan?.checks) ? plan.checks : [])
    if (
      c?.applicability === 'REQUIRED' &&
      !(await verifyGate(boundary, 'check', c, {
        sourceSha256: snapshot?.sourceSha256,
        configSha256: snapshot?.configSha256,
      }))
    )
      add(issues, 'CHECK_PROOF', c?.id, 'Current trusted raw check run required')
  return outcome(issues)
}
import { createHash } from 'node:crypto'
import { lstat, readFile, realpath } from 'node:fs/promises'
import { resolve, sep } from 'node:path'
import { safeRepoPath } from './contracts.mjs'

const boundaries = new WeakSet()

// The root is chosen by a trusted caller. Every component is checked before the file is read.
export function createArtifactReader(root) {
  if (typeof root !== 'string' || !root) throw new TypeError('Artifact root required')
  const base = resolve(root)
  const within = (path) =>
    process.platform === 'win32'
      ? path.toLowerCase().startsWith(`${base}${sep}`.toLowerCase())
      : path.startsWith(`${base}${sep}`)
  return Object.freeze({
    async read(path) {
      if (!safeRepoPath(path)) throw new Error('UNSAFE_ARTIFACT: unsafe relative path')
      let cursor = base
      for (const part of path.split('/')) {
        cursor = resolve(cursor, part)
        if (!within(cursor)) throw new Error('UNSAFE_ARTIFACT: outside root')
        const stat = await lstat(cursor)
        if (stat.isSymbolicLink()) throw new Error('UNSAFE_ARTIFACT: symlink')
      }
      const canonical = await realpath(cursor)
      if (!within(canonical)) throw new Error('UNSAFE_ARTIFACT: realpath escape')
      const bytes = await readFile(cursor)
      return Object.freeze({
        path,
        bytes,
        sha256: createHash('sha256').update(bytes).digest('hex'),
      })
    },
  })
}

// Only a trusted integration supplies verify: it must inspect actual raw artifacts, hashes,
// complete execution, independent receipt, scope and bindings. No JSON field is an authority.
export function createEvidenceBoundary({ verify } = {}) {
  if (typeof verify !== 'function') throw new TypeError('Trusted evidence verifier required')
  const boundary = Object.freeze({ verify: (kind, ref, expected) => verify(kind, ref, expected) })
  boundaries.add(boundary)
  return boundary
}

export const isEvidenceBoundary = (x) => boundaries.has(x)

export async function verifyArtifactHash(reader, descriptor) {
  if (
    typeof reader?.read !== 'function' ||
    !safeRepoPath(descriptor?.path) ||
    !/^[a-f0-9]{64}$/.test(descriptor?.sha256 ?? '')
  )
    return false
  try {
    return (await reader.read(descriptor.path)).sha256 === descriptor.sha256
  } catch {
    return false
  }
}

export async function verifyGate(boundary, kind, ref, expected) {
  if (
    !isEvidenceBoundary(boundary) ||
    !ref ||
    typeof ref !== 'object' ||
    Array.isArray(ref) ||
    ref.kind !== kind ||
    ref.status !== 'PASS' ||
    ref.complete !== true ||
    ref.scope !== 'full' ||
    !safeRepoPath(ref.artifact?.path) ||
    !/^[a-f0-9]{64}$/.test(ref.artifact?.sha256 ?? '') ||
    !ref.bindings ||
    typeof ref.bindings !== 'object' ||
    Object.entries(expected).some(([k, v]) => ref.bindings[k] !== v)
  )
    return false
  try {
    return (await boundary.verify(kind, ref, expected)) === true
  } catch {
    return false
  }
}
import { pathMatches, safeRepoPath, validateManifest } from './contracts.mjs'
import { evaluateTransition } from './lifecycle.mjs'
import { createArtifactReader } from './evidence.mjs'
import { createHash } from 'node:crypto'
import { spawnSync } from 'node:child_process'
import { lstat, readFile, realpath, mkdir, writeFile } from 'node:fs/promises'
import { resolve, dirname, sep, posix, basename } from 'node:path'
import { tmpdir } from 'node:os'

const issue = (issues, code, path, detail) => issues.push({ code, path, detail })
const result = (issues) => ({ ok: issues.length === 0, issues })
const activeRoot = (id) => `openspec/changes/${id}`
const archiveRoot = (date, id) => `openspec/changes/archive/${date}-${id}`
const closurePath = (path) =>
  path.toLowerCase().startsWith('openspec/specs/') ||
  path.toLowerCase().startsWith('openspec/changes/archive/')
const validDate = (date) =>
  typeof date === 'string' &&
  /^\d{4}-\d{2}-\d{2}$/.test(date) &&
  !Number.isNaN(Date.parse(`${date}T00:00:00Z`)) &&
  new Date(`${date}T00:00:00Z`).toISOString().startsWith(date)

export function checkScope(manifest, phase, paths = []) {
  const issues = [...validateManifest(manifest).issues]
  if (!['PLANNING', 'PRE_REVIEW', 'IMPLEMENTATION'].includes(phase))
    issue(issues, 'SCOPE_PHASE', 'phase', 'Use a verified closure plan for closure')
  if (!Array.isArray(paths)) issue(issues, 'SCOPE_PATHS', 'paths', 'Path array required')
  if (!manifest?.scope || !Array.isArray(paths)) return result(issues)
  if (phase === 'IMPLEMENTATION' && manifest.scope.mode !== 'IMPLEMENTATION')
    issue(issues, 'SCOPE_MODE', 'scope.mode', 'Implementation scope is inactive')
  if (phase !== 'IMPLEMENTATION' && !['PLANNING', 'PRE_REVIEW'].includes(manifest.scope.mode))
    issue(issues, 'SCOPE_MODE', 'scope.mode', 'Planning scope is inactive')
  const allowed =
    phase === 'IMPLEMENTATION' ? manifest.scope.allowed : manifest.scope.planningAllowed
  const frozen = Array.isArray(manifest.scope.frozen) ? manifest.scope.frozen : []
  const allowedList = Array.isArray(allowed) ? allowed : []
  for (const [i, path] of paths.entries()) {
    if (!safeRepoPath(path)) {
      issue(issues, 'UNSAFE_PATH', `paths[${i}]`, 'Unsafe relative path')
      continue
    }
    if (closurePath(path)) {
      issue(issues, 'CLOSURE_INACTIVE', `paths[${i}]`, 'Closure requires verified plan')
      continue
    }
    if (frozen.some((p) => pathMatches(p, path)) || !allowedList.some((p) => pathMatches(p, path)))
      issue(issues, 'SCOPE_DENIED', `paths[${i}]`, 'Path outside active scope')
  }
  return result(issues)
}

// Returns an immutable proposal. A later closure executor must recheck hashes, references,
// actual Git ownership and the absence of writes before applying it.
export async function planClosure(options = {}) {
  if (options === null || typeof options !== 'object' || Array.isArray(options))
    return {
      ok: false,
      issues: [{ code: 'CLOSURE_SHAPE', path: '$', detail: 'Options object required' }],
      operations: [],
      originMap: [],
    }
  const { manifest, stageId, date, operations, references, evidence, boundary, snapshot, reader } =
    options
  const issues = [...validateManifest(manifest).issues]
  if (!validDate(date)) issue(issues, 'ARCHIVE_DATE', 'date', 'Canonical real UTC date required')
  const id = manifest?.scope?.closure?.archiveOwner
  if (
    !Array.isArray(manifest?.stages) ||
    manifest.stages.find((s) => s?.id === stageId)?.change !== id
  )
    issue(issues, 'STAGE_OWNER', 'stageId', 'Closure stage must own the selected change')
  const source = activeRoot(id)
  const archive = archiveRoot(date, id)
  const expectedSpecs = Array.isArray(manifest?.scope?.closure?.specDestinations)
    ? manifest.scope.closure.specDestinations
    : []
  if (!Array.isArray(operations))
    issue(issues, 'CLOSURE_OPERATIONS', 'operations', 'Operations required')
  else {
    const sync = operations.filter((op) => op?.type === 'sync')
    const archives = operations.filter((op) => op?.type === 'archive')
    if (
      operations.length !== expectedSpecs.length + 1 ||
      sync.length !== expectedSpecs.length ||
      archives.length !== 1
    )
      issue(
        issues,
        'CLOSURE_OPERATIONS',
        'operations',
        'Exactly declared syncs and one archive required',
      )
    for (const [i, op] of operations.entries()) {
      if (!safeRepoPath(op?.from) || !safeRepoPath(op?.to)) {
        issue(issues, 'UNSAFE_PATH', `operations[${i}]`, 'Unsafe operation path')
        continue
      }
      if (op.type === 'sync') {
        if (
          !expectedSpecs.includes(op.to) ||
          op.from !== `${source}/specs/${op.to.slice('openspec/specs/'.length)}` ||
          (Array.isArray(manifest?.scope?.frozen) &&
            manifest.scope.frozen.some((p) => pathMatches(p, op.to)))
        )
          issue(
            issues,
            'CLOSURE_DESTINATION',
            `operations[${i}]`,
            'Spec sync must use exact own delta and unfrozen destination',
          )
      } else if (op.type === 'archive') {
        if (op.from !== source || op.to !== archive)
          issue(
            issues,
            'ARCHIVE_DESTINATION',
            `operations[${i}]`,
            'Archive must move exact owner change',
          )
      } else issue(issues, 'CLOSURE_OPERATIONS', `operations[${i}]`, 'Unknown operation')
    }
    if (new Set(sync.map((op) => op.to)).size !== expectedSpecs.length)
      issue(issues, 'CLOSURE_DESTINATION', 'operations', 'Duplicate or absent spec destination')
  }
  if (!Array.isArray(references) || !references.length)
    issue(issues, 'REFERENCE_RELOCATION', 'references', 'Owned reference inventory required')
  else
    for (const [i, ref] of references.entries()) {
      if (
        !safeRepoPath(ref?.origin) ||
        !safeRepoPath(ref?.relocated) ||
        !ref.origin.startsWith(`${source}/`) ||
        ref.relocated !== `${archive}${ref.origin.slice(source.length)}` ||
        !/^[a-f0-9]{64}$/.test(ref.sha256 ?? '') ||
        !['owned', 'immutable-origin'].includes(ref.kind)
      )
        issue(
          issues,
          'REFERENCE_RELOCATION',
          `references[${i}]`,
          'Reference mapping must retain exact owner-relative path and hash',
        )
    }
  if (reader !== undefined) {
    if (typeof reader?.read !== 'function')
      issue(issues, 'ARTIFACT_READER', 'reader', 'Safe artifact reader required')
    else {
      for (const [i, op] of (operations ?? []).entries())
        if (op?.type === 'sync') {
          try {
            const artifact = await reader.read(op.from)
            if (
              artifact.sha256 !== op.sourceSha256 ||
              !/^[a-f0-9]{64}$/.test(op.sourceSha256 ?? '')
            )
              issue(
                issues,
                'SOURCE_HASH',
                `operations[${i}]`,
                'Delta spec source bytes differ from bound hash',
              )
          } catch {
            issue(issues, 'SOURCE_HASH', `operations[${i}]`, 'Delta spec source is unreadable')
          }
        }
      for (const [i, ref] of (references ?? []).entries()) {
        try {
          const artifact = await reader.read(ref?.origin)
          if (artifact.sha256 !== ref?.sha256)
            issue(
              issues,
              'REFERENCE_HASH',
              `references[${i}]`,
              'Reference origin bytes differ from bound hash',
            )
        } catch {
          issue(issues, 'REFERENCE_HASH', `references[${i}]`, 'Reference origin is unreadable')
        }
      }
    }
  }
  const gate = await evaluateTransition({
    manifest,
    stageId,
    target: 'ARCHIVE',
    evidence,
    boundary,
    snapshot,
  })
  issues.push(...gate.issues)
  return {
    ok: issues.length === 0,
    issues,
    operations: issues.length ? [] : structuredClone(operations),
    originMap: issues.length ? [] : structuredClone(references),
  }
}

const receipts = new WeakSet()
export function isClosureReceipt(receipt, { manifest, stageId, snapshot } = {}) {
  return (
    !!receipt &&
    receipts.has(receipt) &&
    receipt.owner === manifest?.scope?.closure?.archiveOwner &&
    receipt.stageId === stageId &&
    receipt.scopeSha256 === snapshot?.scopeSha256 &&
    receipt.sourceSha256 === snapshot?.sourceSha256 &&
    receipt.planSha256 === snapshot?.planSha256
  )
}

const sha = (bytes) => createHash('sha256').update(bytes).digest('hex')
const git = (root, ...args) =>
  spawnSync('git', args, {
    cwd: root,
    encoding: 'utf8',
    env: {
      ...process.env,
      GIT_CONFIG_NOSYSTEM: '1',
      GIT_OPTIONAL_LOCKS: '0',
      GIT_CONFIG_GLOBAL: process.platform === 'win32' ? 'NUL' : '/dev/null',
    },
  })
const contained = (base, path) => {
  const a = process.platform === 'win32' ? base.toLowerCase() : base
  const b = process.platform === 'win32' ? path.toLowerCase() : path
  return b === a || b.startsWith(`${a}${sep}`)
}

async function safeFile(root, path) {
  if (!safeRepoPath(path)) throw new Error('UNSAFE_PATH')
  const base = await realpath(root)
  let cursor = base
  for (const part of path.split('/')) {
    cursor = resolve(cursor, part)
    if (!contained(base, cursor)) throw new Error('UNSAFE_PATH')
    const s = await lstat(cursor)
    if (s.isSymbolicLink()) throw new Error('UNSAFE_PATH')
  }
  if (!contained(base, await realpath(cursor))) throw new Error('UNSAFE_PATH')
  return readFile(cursor)
}

async function safeDestination(root, path) {
  if (!safeRepoPath(path)) throw new Error('UNSAFE_PATH')
  const base = await realpath(root)
  let cursor = base
  for (const part of path.split('/')) {
    cursor = resolve(cursor, part)
    if (!contained(base, cursor)) throw new Error('UNSAFE_PATH')
    try {
      const stat = await lstat(cursor)
      if (stat.isSymbolicLink()) throw new Error('UNSAFE_PATH')
    } catch (error) {
      if (error?.code === 'ENOENT') return Buffer.alloc(0)
      throw error
    }
  }
  return safeFile(root, path)
}

function requirementSections(bytes) {
  const text = bytes.toString('utf8')
  const groups = [...text.matchAll(/^## (ADDED|MODIFIED|REMOVED) Requirements\s*$/gm)]
  if (!groups.length) throw new Error('DELTA_REQUIREMENTS')
  const sections = []
  for (const [i, group] of groups.entries()) {
    const body = text.slice(group.index + group[0].length, groups[i + 1]?.index ?? text.length)
    const matches = [...body.matchAll(/^### Requirement: ([A-Z][A-Z0-9]*(?:-[A-Z0-9]+)+)\b.*$/gm)]
    if (!matches.length) throw new Error('DELTA_REQUIREMENTS')
    sections.push(
      ...matches.map((m, j) => ({
        id: m[1],
        mode: group[1],
        body: body.slice(m.index, matches[j + 1]?.index ?? body.length).trimEnd(),
      })),
    )
  }
  if (new Set(sections.map((s) => s.id)).size !== sections.length)
    throw new Error('DELTA_REQUIREMENTS')
  return sections
}

function syncDelta(existing, delta, capability) {
  const source = requirementSections(delta)
  const oldText = existing.toString('utf8')
  const oldMatches = [
    ...oldText.matchAll(/^### Requirement: ([A-Z][A-Z0-9]*(?:-[A-Z0-9]+)+)\b.*$/gm),
  ]
  const head = oldText.trim()
    ? oldMatches.length
      ? oldText.slice(0, oldMatches[0].index).trimEnd()
      : oldText.trimEnd()
    : `# ${capability}\n\n## Requirements`
  const prior = oldMatches.map((m, i) => ({
    id: m[1],
    body: oldText.slice(m.index, oldMatches[i + 1]?.index ?? oldText.length).trimEnd(),
  }))
  for (const section of source) {
    const at = prior.findIndex((x) => x.id === section.id)
    if ((section.mode === 'ADDED' && at >= 0) || (section.mode !== 'ADDED' && at < 0))
      throw new Error('DELTA_REQUIREMENTS')
    if (section.mode === 'REMOVED') prior.splice(at, 1)
    else if (at >= 0) prior[at] = section
    else prior.push(section)
  }
  return Buffer.from(`${head}\n\n${prior.map((s) => s.body).join('\n\n')}\n`)
}

function relocateOwned(bytes, origin, relocated, map, allPaths) {
  let text = bytes.toString('utf8')
  for (const [from, to] of map) text = text.split(from).join(to)
  if (origin.endsWith('.md'))
    text = text.replace(/\]\(([^)#?]+)(#[^)]*)?\)/g, (whole, target, fragment = '') => {
      if (/^[a-z]+:/i.test(target) || target.startsWith('/')) return whole
      const originalTarget = target.startsWith('openspec/')
        ? target
        : posix.normalize(posix.join(posix.dirname(origin), target))
      if (
        !safeRepoPath(originalTarget) ||
        (!allPaths.has(originalTarget) && ![...map.values()].includes(originalTarget))
      )
        throw new Error('REFERENCE_BROKEN')
      const newTarget = map.get(originalTarget) ?? originalTarget
      const next = posix.relative(posix.dirname(relocated), newTarget) || '.'
      return `](${next}${fragment})`
    })
  return Buffer.from(text)
}

// This adapter is deliberately bounded to unconnected disposable Git fixtures.
// It preflights all inventory, bindings and content before the first mutation.
export async function executeClosure(args = {}) {
  if (args === null || typeof args !== 'object' || Array.isArray(args))
    return {
      ok: false,
      issues: [{ code: 'CLOSURE_SHAPE', path: '$', detail: 'Options object required' }],
    }
  const issues = []
  const { root, manifest, stageId, snapshot, expectedHead } = args
  if (!manifest?.scope?.closure?.enabled)
    issue(issues, 'CLOSURE_INACTIVE', 'manifest.scope.closure.enabled', 'Closure not activated')
  let base
  try {
    base = await realpath(root)
    const temp = await realpath(tmpdir())
    if (!contained(temp, base) || !basename(base).startsWith('frade-closure-'))
      throw new Error('Not a disposable closure fixture')
  } catch {
    issue(issues, 'GIT_ROOT', 'root', 'Owned disposable root required')
  }
  if (base) {
    try {
      const dotGit = resolve(base, '.git')
      const actualGit = await realpath(dotGit)
      if (
        !(await lstat(dotGit)).isDirectory() ||
        (process.platform === 'win32'
          ? actualGit.toLowerCase() !== dotGit.toLowerCase()
          : actualGit !== dotGit)
      )
        throw new Error('External Git common directory')
    } catch {
      issue(issues, 'GIT_OWNER', 'root', 'Disposable repository must own its Git directory')
    }
  }
  if (issues.length) return { ok: false, issues }
  const plan = await planClosure({ ...args, reader: createArtifactReader(base) })
  issues.push(...plan.issues)
  if (issues.length) return { ok: false, issues }
  if (base && !issues.some((x) => x.code === 'GIT_OWNER')) {
    const top = git(base, 'rev-parse', '--show-toplevel')
    const branch = git(base, 'branch', '--show-current')
    const head = git(base, 'rev-parse', 'HEAD')
    const remotes = git(base, 'remote')
    const status = git(base, 'status', '--porcelain', '--untracked-files=all', '--ignored')
    const ancestor = git(
      base,
      'merge-base',
      '--is-ancestor',
      manifest?.originalBaseline ?? '',
      'HEAD',
    )
    if (
      top.status !== 0 ||
      (process.platform === 'win32'
        ? resolve(top.stdout.trim()).toLowerCase() !== base.toLowerCase()
        : resolve(top.stdout.trim()) !== base) ||
      branch.stdout.trim() !== manifest?.owner?.branch ||
      remotes.stdout.trim() ||
      status.stdout.trim()
    )
      issue(issues, 'GIT_OWNER', 'root', 'Detached, dirty, connected or foreign repository')
    if (head.status !== 0 || head.stdout.trim() !== expectedHead || ancestor.status !== 0)
      issue(issues, 'GIT_STALE', 'expectedHead', 'Head or original baseline differs')
  }
  if (issues.length) return { ok: false, issues }
  const source = activeRoot(manifest.scope.closure.archiveOwner)
  const archive = archiveRoot(args.date, manifest.scope.closure.archiveOwner)
  const tracked = git(base, 'ls-files', '-z', '--', source).stdout.split('\0').filter(Boolean)
  const allTracked = git(base, 'ls-files', '-z').stdout.split('\0').filter(Boolean)
  if (new Set(allTracked.map((x) => x.toLowerCase())).size !== allTracked.length)
    issue(issues, 'GIT_CASE_COLLISION', 'root', 'Case-colliding tracked paths')
  const refs = Array.isArray(args.references) ? args.references : []
  if (tracked.length !== refs.length || tracked.some((p) => !refs.some((r) => r.origin === p)))
    issue(
      issues,
      'REFERENCE_INVENTORY',
      'references',
      'Every owned tracked file must be mapped exactly once',
    )
  const map = new Map(refs.map((r) => [r.origin, r.relocated]))
  const allPaths = new Set(allTracked)
  const plannedWrites = []
  try {
    for (const op of args.operations.filter((x) => x.type === 'sync')) {
      const delta = await safeFile(base, op.from)
      if (sha(delta) !== op.sourceSha256) throw new Error('SOURCE_HASH')
      if (allTracked.some((p) => p.toLowerCase() === op.to.toLowerCase() && p !== op.to))
        throw new Error('GIT_CASE_COLLISION')
      const old = await safeDestination(base, op.to)
      plannedWrites.push([op.to, syncDelta(old, delta, op.to.split('/')[2])])
    }
    const rawMap = new Map()
    for (const ref of refs) {
      const raw = await safeFile(base, ref.origin)
      if (sha(raw) !== ref.sha256) throw new Error('REFERENCE_HASH')
      rawMap.set(ref.origin, raw)
    }
    const resultMap = new Map(),
      visiting = new Set()
    const targetOf = (origin, value) => {
      if (typeof value !== 'string' || !value || /^[a-z]+:/i.test(value) || value.startsWith('/'))
        return null
      const target = value.startsWith('openspec/')
        ? value
        : posix.normalize(posix.join(posix.dirname(origin), value))
      return safeRepoPath(target) && allPaths.has(target) ? target : null
    }
    const transform = async (origin) => {
      if (resultMap.has(origin)) return resultMap.get(origin)
      if (visiting.has(origin)) throw new Error('REFERENCE_CYCLE')
      visiting.add(origin)
      const ref = refs.find((r) => r.origin === origin)
      const raw = rawMap.get(origin)
      let bytes = raw
      if (ref.kind !== 'immutable-origin' && origin.endsWith('.json')) {
        const walk = async (value) => {
          if (Array.isArray(value)) return Promise.all(value.map(walk))
          if (value && typeof value === 'object') {
            const result = {}
            for (const [key, item] of Object.entries(value)) result[key] = await walk(item)
            if (typeof value.path === 'string' && typeof value.sha256 === 'string') {
              const target = targetOf(origin, value.path)
              if (!target) throw new Error('REFERENCE_BROKEN')
              const before = rawMap.get(target) ?? (await safeFile(base, target))
              if (sha(before) !== value.sha256) throw new Error('ROLE_SOURCE_HASH')
              result.sha256 = sha(rawMap.has(target) ? await transform(target) : before)
            }
            return result
          }
          if (typeof value === 'string') {
            const target = targetOf(origin, value)
            if (!target) return value
            const next = map.get(target) ?? target
            return value.startsWith('openspec/')
              ? next
              : posix.relative(posix.dirname(ref.relocated), next) || '.'
          }
          return value
        }
        bytes = Buffer.from(
          JSON.stringify(await walk(JSON.parse(raw.toString('utf8')))) +
            (raw.at(-1) === 10 ? '\n' : ''),
        )
      } else if (ref.kind !== 'immutable-origin')
        bytes = relocateOwned(raw, origin, ref.relocated, map, allPaths)
      visiting.delete(origin)
      resultMap.set(origin, bytes)
      return bytes
    }
    for (const ref of refs) plannedWrites.push([ref.relocated, await transform(ref.origin)])
    for (const parent of ['openspec', 'openspec/changes', 'openspec/changes/archive']) {
      try {
        const s = await lstat(resolve(base, parent))
        if (s.isSymbolicLink() || !s.isDirectory()) throw new Error('UNSAFE_PATH')
      } catch (error) {
        if (error?.code !== 'ENOENT') throw error
      }
    }
    try {
      await lstat(resolve(base, archive))
      issue(issues, 'ARCHIVE_DESTINATION', 'archive', 'Archive already exists')
    } catch (error) {
      if (error?.code !== 'ENOENT') throw error
    }
  } catch (error) {
    issue(
      issues,
      [
        'REFERENCE_BROKEN',
        'REFERENCE_HASH',
        'SOURCE_HASH',
        'ROLE_SOURCE_HASH',
        'REFERENCE_CYCLE',
        'GIT_CASE_COLLISION',
      ].includes(error?.message)
        ? error.message
        : 'CLOSURE_PREFLIGHT',
      'operations',
      String(error?.message ?? error),
    )
  }
  if (issues.length) return { ok: false, issues }
  try {
    await mkdir(resolve(base, dirname(archive)), { recursive: true })
    const move = git(base, 'mv', '--', source, archive)
    if (move.status !== 0) throw new Error(`git mv: ${move.stderr}`)
    for (const [path, bytes] of plannedWrites) {
      await mkdir(dirname(resolve(base, path)), { recursive: true })
      await writeFile(resolve(base, path), bytes)
    }
    for (const [path, bytes] of plannedWrites)
      if (sha(await safeFile(base, path)) !== sha(bytes))
        throw new Error(`Output hash mismatch: ${path}`)
    try {
      await lstat(resolve(base, source))
      throw new Error('Active owner still exists')
    } catch (error) {
      if (error?.code !== 'ENOENT') throw error
    }
  } catch (error) {
    return {
      ok: false,
      issues: [
        { code: 'CLOSURE_EXECUTION', path: archive, detail: String(error?.message ?? error) },
      ],
    }
  }
  const operationSha256 = sha(
    Buffer.from(
      JSON.stringify({
        operations: plan.operations,
        origins: refs,
        outputs: plannedWrites.map(([path, bytes]) => ({ path, sha256: sha(bytes) })),
      }),
    ),
  )
  const receipt = Object.freeze({
    owner: manifest.scope.closure.archiveOwner,
    stageId,
    scopeSha256: snapshot.scopeSha256,
    sourceSha256: snapshot.sourceSha256,
    planSha256: snapshot.planSha256,
    baseline: manifest.originalBaseline,
    head: expectedHead,
    archive,
    operationSha256,
    origins: Object.freeze(refs.map((x) => Object.freeze({ ...x }))),
  })
  receipts.add(receipt)
  return { ok: true, issues: [], receipt, operations: plan.operations, originMap: plan.originMap }
}

