  'RESEARCH',
  'REQUIREMENTS',
  'PLANNING',
  'PRE_REVIEW',
  'BDD_TDD',
  'IMPLEMENTATION',
  'CHECKS',
  'VERIFICATION',
  'POST_REVIEW',
  'ARCHIVE',
  'CLOSED',
