const RCA_CLASSES = new Set([
  'DOMAIN_MODEL',
  'INVARIANT',
  'ALGORITHM',
  'ABSTRACTION_BOUNDARY',
  'STATE_TRANSITION',
  'TEST',
  'SPEC_CONFLICT',
  'INTEGRATION',
  'ENVIRONMENT',
